import { boot } from 'quasar/wrappers';
import keyboardUtil from 'src/utils/keyboard';
import { safeBoot } from 'src/utils/bootSafety';

export default boot(safeBoot('helpshortcut', () => {
  document.addEventListener('keydown', (e: KeyboardEvent) => {
    // Meta + H for Help
    if (e.keyCode === 72 && keyboardUtil.methods.isMetaKey(e)) {
      e.preventDefault();
      const event = new CustomEvent('openHelpPage', {});
      document.dispatchEvent(event);
      return;
    }

    // Meta + I for About (Info)
    if (e.keyCode === 73 && keyboardUtil.methods.isMetaKey(e)) {
      e.preventDefault();
      const event = new CustomEvent('openAboutDialog', {});
      document.dispatchEvent(event);
      return;
    }

    // Ctrl/Cmd + Shift + P — Performance Analysis & Support Ticket
    if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toUpperCase() === 'P') {
      e.preventDefault();
      document.dispatchEvent(new CustomEvent('openPerformanceAnalysis'));
      return;
    }
  });
}));
